#include "ResidencyAuthority.hpp"
namespace elysium::streaming { void ResidencyAuthority::submit(ResidencyRequest r){if(!r.address)return;queue_.push_back(r);} std::vector<ResidencyRequest> ResidencyAuthority::orderedQueue()const{auto q=queue_;std::sort(q.begin(),q.end(),[](auto&a,auto&b){if(a.viewerRevision!=b.viewerRevision)return a.viewerRevision>b.viewerRevision;if(a.priority!=b.priority)return a.priority>b.priority;return a.address<b.address;});return q;} std::optional<ResidentHandle> ResidencyAuthority::publish(Candidate c){if(c.cancelled||c.request.viewerRevision<minRevision_)return std::nullopt;ResidentHandle h{c.request.address,c.request.interactionProxy?Lod::Editable:c.request.lod,c.generation};resident_[h.address]=h;return h;} void ResidencyAuthority::cancelBefore(std::uint64_t r){minRevision_=std::max(minRevision_,r);queue_.erase(std::remove_if(queue_.begin(),queue_.end(),[&](auto&q){return q.viewerRevision<minRevision_;}),queue_.end());} void ResidencyAuthority::unload(Address a){resident_.erase(a);} std::optional<ResidentHandle> ResidencyAuthority::resident(Address a)const{auto i=resident_.find(a);if(i==resident_.end())return std::nullopt;return i->second;} std::size_t ResidencyAuthority::residentCount(Lod l)const{std::size_t n=0;for(auto&[_,h]:resident_)if(h.lod==l)++n;return n;} }